#include "sturdy_rs/device.hpp"

#include <optional>
#include <string>

#include <Core/BackendInventory.hpp>
#include <Engine/Engine.hpp>
#include <RHI/RHI.hpp>

// Generated by build.rs from src/device.rs.
#include "sturdy_rs/device_bridge.h"

namespace sturdy_rs::device {
    namespace {

        namespace E = SFT::Engine;
        namespace R = SFT::RHI;

        rust::String rs(const std::string &text) { return rust::String::lossy(text.data(), text.size()); }

        DeviceBackend to_bridge(R::BackendType backend) noexcept {
            switch (backend) {
                case R::BackendType::Vulkan: return DeviceBackend::Vulkan;
                case R::BackendType::D3D12: return DeviceBackend::D3D12;
                case R::BackendType::Metal: return DeviceBackend::Metal;
                case R::BackendType::WebGpu: return DeviceBackend::WebGpu;
            }
            return DeviceBackend::Auto;
        }

        std::optional<R::BackendType> from_bridge(DeviceBackend backend) noexcept {
            switch (backend) {
                case DeviceBackend::Vulkan: return R::BackendType::Vulkan;
                case DeviceBackend::D3D12: return R::BackendType::D3D12;
                case DeviceBackend::Metal: return R::BackendType::Metal;
                case DeviceBackend::WebGpu: return R::BackendType::WebGpu;
                case DeviceBackend::Auto: break;
            }
            return std::nullopt;
        }

        // The bridge enums are declared in the same order as the C++ ones, so the integral cast is exact; these
        // assertions keep the two in step.
        template <typename Bridge, typename Native>
        constexpr bool same(Bridge bridge, Native native) noexcept {
            return static_cast<int>(bridge) == static_cast<int>(native);
        }
        static_assert(same(DevicePreference::DiscreteOnly, E::DevicePreference::DiscreteOnly) &&
                      same(DevicePreference::IntegratedOnly, E::DevicePreference::IntegratedOnly));
        static_assert(same(DeviceSwitchOutcome::Failed, E::DeviceSwitchOutcome::Failed) &&
                      same(DeviceSwitchOutcome::SwitchedWithFallback, E::DeviceSwitchOutcome::SwitchedWithFallback));
        static_assert(same(AdapterPresentability::No, E::AdapterPresentability::No));
        static_assert(same(DeviceChangeKind::LostUnrecoverable, E::DeviceChangeKind::LostUnrecoverable) &&
                      same(DeviceChangeKind::Recovered, E::DeviceChangeKind::Recovered));

        DevicePreference to_bridge(E::DevicePreference value) noexcept { return static_cast<DevicePreference>(value); }
        E::DevicePreference from_bridge(DevicePreference value) noexcept { return static_cast<E::DevicePreference>(value); }

    } // namespace

    rust::Vec<DeviceBackend> available_backends(const EngineView &engine) {
        rust::Vec<DeviceBackend> out;
        for (R::BackendType backend : engine.available_backends()) {
            out.push_back(to_bridge(backend));
        }
        return out;
    }

    namespace {
        rust::Vec<AdapterInfo> to_bridge(const std::vector<E::AdapterDescription> &adapters) {
            rust::Vec<AdapterInfo> out;
            for (const E::AdapterDescription &adapter : adapters) {
                AdapterInfo info{};
                info.stable_id = rs(adapter.stable_id);
                info.physical_device_id = rs(adapter.physical_device_id);
                info.name = rs(adapter.name);
                info.vendor = rs(adapter.vendor);
                info.vendor_id = adapter.vendor_id;
                info.device_id = adapter.device_id;
                info.device_type = rust::String(R::device_type_name(adapter.device_type));
                for (const E::BackendOffer &offer : adapter.backends) {
                    BackendOfferInfo entry{};
                    entry.backend = to_bridge(offer.backend);
                    entry.driver_version = rs(offer.driver_version);
                    entry.api_version = rs(offer.api_version);
                    entry.presentable = static_cast<AdapterPresentability>(offer.presentable);
                    entry.active = offer.active;
                    info.backends.push_back(std::move(entry));
                }
                out.push_back(std::move(info));
            }
            return out;
        }
    } // namespace

    rust::Vec<AdapterInfo> enumerate_adapters() {
        const R::GpuInventory inventory = SFT::Core::enumerate_gpu_inventory(
            R::InstanceDesc{.application_name = "Sturdy GPU enumeration", .engine_name = "SturdyEngine5", .headless = true});
        return to_bridge(E::describe_adapters(inventory, std::nullopt, {}));
    }

    rust::Vec<AdapterInfo> available_adapters(EngineView &engine) { return to_bridge(engine.available_adapters()); }

    DeviceSwitchInfo switch_device(EngineView &engine, const DeviceRequestInfo &request) {
        E::DeviceRequest native;
        native.backend = from_bridge(request.backend);
        if (!request.adapter_id.empty()) {
            native.adapter_id = std::string(request.adapter_id);
        }
        native.preference = from_bridge(request.preference);
        native.force_recreate = request.force_recreate;

        const E::DeviceSwitchResult result = engine.switch_device(native);
        DeviceSwitchInfo info{};
        info.outcome = static_cast<DeviceSwitchOutcome>(result.outcome);
        info.reason = rs(result.reason);
        info.backend = to_bridge(result.backend);
        info.adapter_name = rs(result.adapter_name);
        info.adapter_stable_id = rs(result.adapter_stable_id);
        info.generation = result.generation;
        info.rolled_back = result.rolled_back;
        return info;
    }

    std::uint64_t device_generation(const EngineView &engine) noexcept { return engine.device_generation(); }

    rust::Vec<DeviceChangeInfo> take_device_change_events(EngineView &engine) {
        rust::Vec<DeviceChangeInfo> out;
        for (const E::DeviceChangeEvent &event : engine.take_device_change_events()) {
            DeviceChangeInfo info{};
            info.kind = static_cast<DeviceChangeKind>(event.kind);
            info.generation = event.generation;
            info.backend = to_bridge(event.backend);
            info.adapter_name = rs(event.adapter_name);
            info.message = rs(event.message);
            out.push_back(std::move(info));
        }
        return out;
    }

} // namespace sturdy_rs::device
